// [LAW:types-are-the-program] The variable schema: a AuthoredVariableDecl is discriminated
// by `kind` (literal / input / env / file / shell / template / time / state),
// declared as DATA (VARIABLE_SCHEMA) and interpreted by the tag-by-field-value
// engine (taggedUnion). Each arm is a `fields` schema over its member's non-`kind`
// fields, except `input`, whose `default` must match its `type` — a genuine
// cross-field invariant carried as a closure. This file changes when a source
// kind's shape changes; adding a kind is one new arm here plus its runtime impl.

import {
  type ParseDecl,
  type SourceDefault,
  type DslConfig,
  type EnvVarDecl,
  type FileVarDecl,
  type InputVarDecl,
  type LiteralVarDecl,
  type ShellVarDecl,
  type StateVarDecl,
  type TemplateVarDecl,
  type TimeVarDecl,
  type AuthoredVariableDecl,
  type SegmentDecl,
  type ResolvedSegmentDecl,
  type ResolvedVariableDecl,
  type ValidatedConfig,
  type VariableDecl,
} from "../dsl-types.js";
import { isJsonValue } from "../../var-system/types.js";
import { findKeyLine } from "./diagnostics.js";
import {
  armFacets,
  describeType,
  describeValue,
  fields,
  isPlainObject,
  oneOfPresent,
  refuseRemoved,
  oneOfPresentJson,
  optionalStringField,
  optionalStringSpec,
  optionalTypedDefault,
  reject,
  requireStringSpec,
  optionalEnvNamesSpec,
  optionalEnumSpec,
  taggedUnion,
  taggedUnionJson,
  type FieldSpec,
  type FieldSpecMap,
  type JsonNode,
  type OneOfPresentSchema,
  type TaggedArm,
  type TaggedUnionSchema,
  type ValidateCtx,
} from "./validate-core.js";
import { requireCacheSpec } from "./cache.js";
import {
  RETIRED_INPUT_PATHS,
  retiredGitKindMessage,
} from "./retired-variables.js";

export function validateVariables(
  ctx: ValidateCtx,
  pathPrefix: string,
  raw: unknown,
): Record<string, AuthoredVariableDecl> {
  if (raw === undefined) return {};
  if (!isPlainObject(raw)) {
    ctx.issues.push({
      path: pathPrefix,
      message: `${pathPrefix} must be an object, got ${describeType(raw)}`,
      line: findKeyLine(ctx.source, pathPrefix.split(".")),
    });
    return {};
  }

  const out: Record<string, AuthoredVariableDecl> = {};
  for (const [name, decl] of Object.entries(raw)) {
    const parsed = taggedUnion(
      ctx,
      VARIABLE_SCHEMA,
      `${pathPrefix}.${name}`,
      decl,
    );
    if (parsed !== null) out[name] = parsed;
  }
  return out;
}

// [LAW:types-are-the-program] `value` is a required union literal with a bespoke
// message whose line points at the variable (not `.value`) — a custom spec, since
// the generic string/enum specs encode different line behavior.
function literalValueSpec(): FieldSpec<string | number | boolean> {
  return {
    required: true,
    json: { type: ["string", "number", "boolean"] },
    parse: (ctx, path, _field, raw) => {
      const value = raw.value;
      if (
        typeof value !== "string" &&
        typeof value !== "number" &&
        typeof value !== "boolean"
      ) {
        ctx.issues.push({
          path: `${path}.value`,
          message: `literal value must be string|number|boolean, got ${describeType(value)}`,
          line: findKeyLine(ctx.source, path.split(".")),
        });
        return undefined;
      }
      return value;
    },
  };
}

// [LAW:one-source-of-truth] Validation and the resolved declaration use the
// same type for an omitted input/template type.
const DEFAULT_VARIABLE_TYPE = "string";
const VARIABLE_TYPES = [DEFAULT_VARIABLE_TYPE, "number", "boolean"] as const;
const VARIABLE_TYPE = optionalEnumSpec(VARIABLE_TYPES);

// [LAW:types-are-the-program] A typed variable's `default` (`input`,
// `template`) carries the cross-field invariant — it must match the declared
// `type` (an absent or invalid `type` defaults the check to "string"). A field spec receives the WHOLE record, so it
// reads its sibling `raw.type` to pick the expected type WITHOUT re-reporting a
// bad type (the `type` field spec owns that error — reading raw here avoids the
// duplicate issue). This is what lets `input` derive BOTH `parse` and `json` from
// one field map via `arm()`, like every other arm — closing the last spot where
// the two interpreters were authored independently [LAW:one-source-of-truth].
function typedDefaultSpec(): FieldSpec<string | number | boolean> {
  return {
    required: false,
    json: { type: ["string", "number", "boolean"] },
    parse: (ctx, path, _field, raw) => {
      const expected =
        VARIABLE_TYPES.find((type) => type === raw.type) ??
        DEFAULT_VARIABLE_TYPE;
      return optionalTypedDefault(ctx, path, raw, expected);
    },
  };
}

function hasResolvedType(decl: VariableDecl): decl is ResolvedVariableDecl {
  return (
    (decl.kind !== "input" && decl.kind !== "template") ||
    decl.type !== undefined
  );
}

function hasResolvedTypes(
  decls: Readonly<Record<string, VariableDecl>>,
): decls is Readonly<Record<string, ResolvedVariableDecl>> {
  return Object.values(decls).every(hasResolvedType);
}

function resolveTypes(
  decls: Readonly<Record<string, VariableDecl>>,
): Readonly<Record<string, ResolvedVariableDecl>> {
  if (hasResolvedTypes(decls)) return decls;
  return Object.fromEntries(
    Object.entries(decls).map(
      ([name, decl]): [string, ResolvedVariableDecl] => [
        name,
        hasResolvedType(decl) ? decl : { ...decl, type: DEFAULT_VARIABLE_TYPE },
      ],
    ),
  );
}

// [LAW:parse-dont-validate] A segment that already holds these resolved
// locals needs no replacement. This includes a segment with no locals.
function usesResolvedLocals(
  segment: SegmentDecl,
  locals: ResolvedSegmentDecl["vars"],
): segment is ResolvedSegmentDecl {
  return segment.vars === locals;
}

function resolveSegmentTypes(segment: SegmentDecl): ResolvedSegmentDecl {
  const locals =
    segment.vars === undefined ? undefined : resolveTypes(segment.vars);
  return usesResolvedLocals(segment, locals)
    ? segment
    : { ...segment, vars: locals };
}

// [LAW:single-enforcer] Lower global and segment-local declarations at the
// final loader checkpoint so synthesized declarations use the same rule.
export function resolveVariableTypes(
  config: DslConfig,
): Pick<ValidatedConfig, "variables" | "segments"> {
  return {
    variables: resolveTypes(config.variables),
    segments: Object.fromEntries(
      Object.entries(config.segments).map(
        ([name, segment]): [string, ResolvedSegmentDecl] => [
          name,
          resolveSegmentTypes(segment),
        ],
      ),
    ),
  };
}

// [LAW:types-are-the-program] The parse-step schema as DATA, through the same
// tag-by-present-key engine `cache:` runs through: text/json are flags whose
// value is the literal true (like cache.never); regex is a pattern string.
// [LAW:single-enforcer] Whether the pattern compiles and has its group 1 is
// the host's judge's to say, where the run is subscribed: a pattern here is
// any string, and nothing on this side compiles it.
const PARSE_SCHEMA: OneOfPresentSchema<ParseDecl> = {
  noun: "parse",
  arms: {
    text: {
      json: { const: true },
      parse: (ctx, path, value) =>
        value === true
          ? { text: true }
          : reject(
              ctx,
              path,
              `parse.text must be the literal boolean true, got ${describeValue(value)}`,
            ),
    },
    regex: {
      json: { type: "string" },
      parse: (ctx, path, value) =>
        typeof value === "string"
          ? { regex: value }
          : reject(
              ctx,
              path,
              `parse.regex must be a pattern string, got ${describeValue(value)}`,
            ),
    },
    json: {
      json: { const: true },
      parse: (ctx, path, value) =>
        value === true
          ? { json: true }
          : reject(
              ctx,
              path,
              `parse.json must be the literal boolean true, got ${describeValue(value)}`,
            ),
    },
  },
};

// [LAW:one-source-of-truth] The `parse` field: absent means the text arm, and
// that default is spelled ONCE, in declareOne's lowering — the decl records
// what the author wrote. The retired top-level `regex:` is reported HERE
// because a variable arm's field map ignores keys it does not declare: an old
// config would otherwise load with its regex silently dropped
// [LAW:no-silent-failure].
function parseSpec(): FieldSpec<ParseDecl> {
  return {
    required: false,
    json: oneOfPresentJson(PARSE_SCHEMA),
    parse: (ctx, path, _field, raw) => {
      if (raw.regex !== undefined) {
        ctx.issues.push({
          path: `${path}.regex`,
          message: `${path}.regex was retired; the regex is the parse step's regex arm now: parse: { regex: ${JSON.stringify(raw.regex)} }`,
          line: findKeyLine(ctx.source, [...path.split("."), "regex"]),
        });
      }
      return raw.parse === undefined
        ? undefined
        : (oneOfPresent(ctx, PARSE_SCHEMA, `${path}.parse`, raw.parse) ??
            undefined);
    },
  };
}

// [LAW:types-are-the-program] A source's `default` lives in its parser's
// OUTPUT domain — a string for the text/regex arms, any JSON value for the
// json arm — so this spec reads its sibling `raw.parse` to pick the domain,
// the way typedDefaultSpec reads `raw.type`. This is THE enforcer of the
// arm↔default pairing: FileVarDecl/ShellVarDecl type `default` as the union
// of both domains and declareOne's lowering trusts the stamp. The sibling's
// own errors are parseSpec's to report: the json domain is the json key
// PRESENT on the raw `parse:` — the tag of that present-key union — never a
// fallthrough over keys it does not recognise.
function sourceDefaultSpec(): FieldSpec<SourceDefault> {
  return {
    required: false,
    json: {
      type: ["string", "number", "boolean", "array", "object"],
      description:
        "The value published when the source fails: a string under the text/regex parse arms, any non-null JSON value under the json arm",
    },
    parse: (ctx, path, _field, raw) =>
      isPlainObject(raw.parse) && "json" in raw.parse
        ? jsonDefault(ctx, path, raw.default)
        : optionalStringField(ctx, path, raw, "default"),
  };
}

function jsonDefault(
  ctx: ValidateCtx,
  path: string,
  value: unknown,
): SourceDefault | undefined {
  if (value === undefined) return undefined;
  return isSourceDefault(value)
    ? value
    : (reject<SourceDefault>(
        ctx,
        `${path}.default`,
        `${path}.default must be a JSON value (a json-parsed source's document), got ${describeValue(value)}`,
      ) ?? undefined);
}

// [LAW:parse-dont-validate] The stamp for the json arm's default: a config
// file's values are JSON-shaped by construction (JSON5 admits Infinity/NaN,
// which JSON does not), a programmatic config's are whatever TS let through.
function isSourceDefault(value: unknown): value is SourceDefault {
  return value !== null && isJsonValue(value);
}

// [LAW:dataflow-not-control-flow] Each arm's field set is DATA over the member's
// non-`kind` fields; the engine supplies the discriminator. `fields` runs every
// spec (reporting all issues) and fails the arm when a required field is absent
// or invalid — the conditional-spread + result-threading the old switch hand-rolled.
const LITERAL_FIELDS: FieldSpecMap<Omit<LiteralVarDecl, "kind">> = {
  value: literalValueSpec(),
  default: optionalStringSpec(),
};
// [LAW:no-silent-failure] An input's path names a payload field; one the
// payload no longer carries would publish the default forever, so it is
// refused with what replaced it (RETIRED_INPUT_PATHS).
function inputPathSpec(): FieldSpec<string> {
  const text = requireStringSpec();
  return {
    ...text,
    parse: (ctx, path, field, raw) => {
      const value = text.parse(ctx, path, field, raw);
      const instead =
        value === undefined ? undefined : RETIRED_INPUT_PATHS.get(value);
      return instead === undefined
        ? value
        : (reject<string>(
            ctx,
            `${path}.${field}`,
            `${path}.${field} "${value}" is no longer in the payload: ${instead}`,
          ) ?? undefined);
    },
  };
}

const INPUT_FIELDS: FieldSpecMap<Omit<InputVarDecl, "kind">> = {
  path: inputPathSpec(),
  type: VARIABLE_TYPE,
  default: typedDefaultSpec(),
};
const ENV_FIELDS: FieldSpecMap<Omit<EnvVarDecl, "kind">> = {
  name: requireStringSpec(),
  default: optionalStringSpec(),
};
const FILE_FIELDS: FieldSpecMap<Omit<FileVarDecl, "kind">> = {
  path: requireStringSpec(),
  readMode: optionalEnumSpec(["whole", "first-line"] as const),
  parse: parseSpec(),
  cache: requireCacheSpec("file"),
  default: sourceDefaultSpec(),
};
const SHELL_FIELDS: FieldSpecMap<Omit<ShellVarDecl, "kind">> = {
  command: requireStringSpec(),
  env: optionalEnvNamesSpec(),
  parse: parseSpec(),
  cache: requireCacheSpec("shell"),
  default: sourceDefaultSpec(),
};
// [LAW:one-source-of-truth] The refusal a kind that takes no cache policy gives
// a `cache:`, spelled once; each kind supplies only why it needs none.
function noCachePolicy(why: string): Readonly<Record<string, string>> {
  return { cache: `${why}, so it takes no cache policy — delete the key` };
}
const TEMPLATE_FIELDS: FieldSpecMap<Omit<TemplateVarDecl, "kind">> = {
  template: requireStringSpec(),
  type: VARIABLE_TYPE,
  default: typedDefaultSpec(),
};
// [LAW:no-silent-failure] A template variable is a computed that tracks every
// variable it reads; a `cache:` was accepted here and never reached the runtime,
// so a ttl, a depends_on or a key changed nothing.
const TEMPLATE_VAR_REMOVED = noCachePolicy(
  "a template variable recomputes whenever a variable it reads changes",
);
const TIME_FIELDS: FieldSpecMap<Omit<TimeVarDecl, "kind">> = {
  layout: requireStringSpec(),
  default: optionalStringSpec(),
};
// [LAW:no-silent-failure] A time variable reads the instant its render is drawn
// at, so it changes exactly when the time it shows does; a `cache:` ttl once set
// how often it re-read the wall clock, and would now change nothing.
const TIME_VAR_REMOVED = noCachePolicy(
  "a time variable reads the instant its render is drawn at",
);
// `within` is synthesis-only: no file may author it.
const STATE_FIELDS: FieldSpecMap<Omit<StateVarDecl, "kind" | "within">> = {
  key: requireStringSpec(),
  default: optionalStringSpec(),
};

// [LAW:one-source-of-truth] The discriminator's name, spelled once: the schema's
// `tag` and every arm's baked-in const / legal-key set read this one constant, so
// a rename cannot leave one facet describing a different field than the other.
const VARIABLE_TAG = "kind";

// [LAW:decomposition] A regular arm parses its non-`kind` fields via `fields` and
// re-attaches the tag the engine already validated; null threading is preserved.
// Its other two facets — the member's JSON schema and the key set the loader
// rejects against — are `armFacets` over the SAME field map `fields` validates,
// so a field added here reaches all three interpreters at once.
function arm<
  K extends AuthoredVariableDecl["kind"],
  M extends Omit<Extract<AuthoredVariableDecl, { kind: K }>, "kind">,
>(
  kind: K,
  fieldMap: FieldSpecMap<M>,
  removed: Readonly<Record<string, string>> = {},
): TaggedArm<Extract<AuthoredVariableDecl, { kind: K }>> {
  return {
    ...armFacets(VARIABLE_TAG, kind, fieldMap),
    parse: (ctx: ValidateCtx, path: string, raw: Record<string, unknown>) => {
      refuseRemoved(ctx, removed, path, raw);
      const body = fields(ctx, fieldMap, path, raw);
      // [LAW:types-are-the-program] `fieldMap: FieldSpecMap<M>` is checked against
      // the member's non-`kind` fields at each call site, so {kind, ...body} IS the
      // member; TS can't relate the reconstruction to the distributed Extract for a
      // generic K, hence the cast — the call-site check carries the real guarantee.
      return body === null
        ? null
        : ({ kind, ...body } as unknown as Extract<
            AuthoredVariableDecl,
            { kind: K }
          >);
    },
  };
}

const VARIABLE_SCHEMA: TaggedUnionSchema<AuthoredVariableDecl, "kind"> = {
  tag: VARIABLE_TAG,
  noun: "source kind",
  // `Unknown shell variable key "readMode". Expected one of: kind, command,
  // parse, cache, default` — a field from the wrong arm, or a typo'd one, is the
  // loud error a segment's has always been (brandon-config-9li). The author of a
  // config they cannot see rendered has no other signal [LAW:no-silent-failure].
  memberNoun: "variable",
  arms: {
    literal: arm("literal", LITERAL_FIELDS),
    // [LAW:one-source-of-truth] `input`'s `default`/`type` cross-field invariant
    // lives in `typedDefaultSpec` (a field spec reading its sibling), so `input`
    // is one field map like every other arm — `arm()` derives both `parse` and
    // `json` from INPUT_FIELDS, no hand-authored schema to keep in sync.
    input: arm("input", INPUT_FIELDS),
    env: arm("env", ENV_FIELDS),
    file: arm("file", FILE_FIELDS),
    shell: arm("shell", SHELL_FIELDS),
    template: arm("template", TEMPLATE_FIELDS, TEMPLATE_VAR_REMOVED),
    time: arm("time", TIME_FIELDS, TIME_VAR_REMOVED),
    state: arm("state", STATE_FIELDS),
  },
  retired: { git: retiredGitKindMessage },
};

// [LAW:one-source-of-truth] One AuthoredVariableDecl's schema, derived from the SAME
// VARIABLE_SCHEMA the validator interprets — the tag-by-kind anyOf.
export function variableDeclJson(): JsonNode {
  return taggedUnionJson(VARIABLE_SCHEMA);
}

// [LAW:one-source-of-truth] The `variables` block (and a segment's nested `vars`)
// is a name → AuthoredVariableDecl map; both surfaces emit this one shape, symmetric to
// both calling `validateVariables`.
export function variablesMapJson(): JsonNode {
  return { type: "object", additionalProperties: variableDeclJson() };
}
