// [LAW:no-silent-failure] How long one run of a shell source may take. The
// launcher's output bound ends a child that writes without end; this ends one
// that never writes, which would otherwise hold its entry open for the life
// of the daemon, and so for every declaration sharing it. A run past it is
// failed in its read phase, naming the bound.
// [LAW:no-mode-explosion] Not a config knob: one bound, named where chosen.
export const SHELL_READ_TIMEOUT_MS = 10_000;

// ─── Readers ─────────────────────────────────────────────────────────────────

// [LAW:effects-at-boundaries] A reader is the effect half of a run: it
// performs the read and classifies its own failure (a non-zero exit, an
// unreadable file, a read its owner abandoned) as a value. `where` names the
// text's origin for the parser's failure message ("regex no-match in output
// of \"uptime\"").
interface SourceReader {
  readonly where: string;
  read(): Promise<Outcome<string>>;
}

// The directory is part of the origin: a command that asks about "this repo"
// answers differently per directory, so every failure — exit, regex
// no-match, JSON parse — names where it ran.
const whereOf = (read: SourceRead): string =>
  read.kind === "shell"
    ? `output of "${read.command}" in ${read.cwd}`
    : `"${read.path}"`;

function shellReader(
  launcher: Launcher,
  read: Extract<SourceRead, { kind: "shell" }>,
  env: Environment,
  signal: AbortSignal,
): SourceReader {
  const { command, cwd } = read;
  return {
    where: whereOf(read),
    read: async () => {
      const r = await launcher.launch({
        bin: "/bin/sh",
        args: ["-c", command],
        cwd,
        // [LAW:one-source-of-truth] Exactly the variables the run's identity
        // carries, so nothing its digest does not hold can move its output.
        environment: env,
        category: "user-shell",
        timeoutMs: SHELL_READ_TIMEOUT_MS,
        signal,
      });
      if (r.ok) return ok(r.stdout);
      // The reason, not the exit code, says which: a child the launcher ended
      // (timeout, output-limit, an abandoned read's abort) can still exit
      // with a code of its own.
      return failed(
        `shell "${command}" ${failureText(r, ` in ${cwd}`)}`,
        "read",
      );
    },
  };
}

function fileReader(
  files: SourceFiles,
  filePath: string,
  readMode: ReadMode,
  signal: AbortSignal,
): SourceReader {
  return {
    where: whereOf({ kind: "file", path: filePath, readMode }),
    read: async () => {
      const read = await files.read(filePath, signal);
      if (read.kind === "text")
        return ok(
          readMode === "first-line"
            ? (read.text.split(/\r?\n/)[0] ?? "")
            : read.text,
        );
      // [LAW:no-silent-failure] The errno distinguishes absence, permission
      // failures, directories and link loops.
      return failed(
        signal.aborted
          ? `file read aborted: ${String(signal.reason)}`
          : `file unreadable (${read.code ?? read.message}): ${filePath}`,
        "read",
      );
    },
  };
}

function readerOf(
  files: SourceFiles,
  launcher: Launcher,
  { run: { identity }, env }: SessionRun,
  signal: AbortSignal,
): SourceReader {
  const { read } = identity;
  switch (read.kind) {
    case "shell":
      return shellReader(launcher, read, env, signal);
    case "file":
      return fileReader(files, read.path, read.readMode, signal);
  }
}

// The parse step over a read's outcome: a failed read passes through
// untouched (it already names its origin); a failed parse gains the origin.
function parsed(
  read: Outcome<string>,
  parser: Parser<JsonValue>,
  where: string,
): Outcome<JsonValue> {
  if (read.kind !== "ok") return read;
  const out = parser(read.value);
  return out.kind === "failed"
    ? failed(`${out.reason} in ${where}`, out.failedAt)
    : out;
}

// ─── PathWatches ──────────────────────────────────────────────────────────────

// What a watch says to each subscriber: why it may be missing changes to its
// path right now, or `null` when it hears every place the path can change.
type WatchFault = (fault: string | null) => void;

interface WatchEntry {
  // Where the path can change, as last derived from disk, and the watcher
  // registry's watch on it.
  bound: BoundWatch;
  // Each subscriber's update, and where it hears the watch's fault.
  readonly subscribers: Map<() => void, WatchFault>;
}

// [LAW:single-enforcer] One watch per path regardless of subscriber count:
// several entries can share it. The watches are the watcher registry's, which
// opens, shares, counts and logs every one in the daemon; this follows each
// path's spec and fans its windows out.
//
// A path is watched wherever it can change (`watchTargetsOf`, the rule the
// config watcher shares): each hop of its link chain polled, and a directory
// watched whole. A link re-pointed on the way is a new spec the next window
// follows.
class PathWatches {
  private readonly entries = new Map<string, WatchEntry>();
  private readonly releaseDelivery: () => void;

  constructor(
    private readonly watchers: WatcherRegistry,
    private readonly fileEvents: FileEvents,
  ) {
    this.releaseDelivery = fileEvents.subscribe((notice) =>
      this.noticed(notice),
    );
  }

  subscribe(
    filePath: string,
    callback: () => void,
    onFault: WatchFault,
  ): () => void {
    const entry = this.entries.get(filePath) ?? this.arm(filePath);
    entry.subscribers.set(callback, onFault);
    onFault(this.faultOf(filePath, entry));
    return () => this.unsubscribe(filePath, callback);
  }

  private arm(filePath: string): WatchEntry {
    const watch = derived(filePath);
    const entry: WatchEntry = {
      bound: {
        derived: watch,
        held: this.watchers.follow(null, watch, () =>
          this.heard(filePath, entry),
        ).watch,
      },
      subscribers: new Map(),
    };
    this.entries.set(filePath, entry);
    return entry;
  }

  // Derive where the path can change, follow it, and say the watch's fault.
  // A new key acquires its watch, keeping every directory both keys name.
  private rederive(filePath: string, entry: WatchEntry): void {
    const paths = derived(filePath);
    const { watch } = this.watchers.follow(entry.bound.held, paths, () =>
      this.heard(filePath, entry),
    );
    entry.bound = { derived: paths, held: watch };
    this.report(filePath, entry);
  }

  // A window re-derives and re-reads: every path it watches is one the
  // content can change at.
  private heard(filePath: string, entry: WatchEntry): void {
    this.rederive(filePath, entry);
    for (const cb of entry.subscribers.keys()) cb();
  }

  private report(filePath: string, entry: WatchEntry): void {
    const fault = this.faultOf(filePath, entry);
    for (const onFault of entry.subscribers.values()) onFault(fault);
  }

  // The watch's fault, derived from what it holds now and whether the OS is
  // delivering what it would hear. A stall is the fault only of a watch that
  // rides the delivery owner's stream: a file is polled and keeps refreshing
  // through one, and a directory watched whole does not.
  private faultOf(filePath: string, entry: WatchEntry): string | null {
    const { handle } = entry.bound.held;
    return watchFault(
      `watch_file ${filePath}`,
      entry.bound,
      handle.ridesStream ? stallReason(this.fileEvents.delivery()) : null,
    );
  }

  // [LAW:no-silent-failure] Delivery moved or a span closed, so the watches
  // may have missed events: each watch re-derives where its path can change,
  // since a directory may have appeared unheard, which says its fault, and
  // every subscriber re-reads as if its own watch had reported. Both together,
  // so no entry drops a stall's fault without reading again, and in one
  // action, so one change of delivery is one publish of every entry's.
  private noticed(notice: DeliveryNotice): void {
    switch (notice.kind) {
      case "period":
        return;
      case "moved":
      case "caught-up":
        // [LAW:single-enforcer] A missed span is heard as a window is.
        runInAction(() => {
          for (const [filePath, entry] of this.entries)
            this.heard(filePath, entry);
        });
        return;
    }
  }

  private unsubscribe(filePath: string, callback: () => void): void {
    const entry = this.entries.get(filePath);
    if (!entry) return;
    entry.subscribers.delete(callback);
    if (entry.subscribers.size === 0) {
      entry.bound.held.handle.release();
      this.entries.delete(filePath);
    }
  }

  dispose(): void {
    this.releaseDelivery();
    for (const entry of this.entries.values())
      entry.bound.held.handle.release();
    this.entries.clear();
  }

  size(): number {
    return this.entries.size;
  }
}

// Where the path can change: every hop of its link chain, polled, and the
// path itself watched whole when it is a directory.
const derived = (filePath: string): PathsWatch =>
  watchTargetsOf({ named: [filePath], whole: [filePath] });

// ─── SourceRuns ──────────────────────────────────────────────────────────────

// [LAW:types-are-the-program] What a declaration holds: the run's reading as
// it stands (observable, so a declaration publishes in the turn it lands) and
// its watch's fault, read the same way; and the digest, for the record.
export interface SourceLane {
  readonly digest: string;
  current(): Current<JsonValue>;
  // Why the run cannot be trusted to answer: the judge refused it, or its
  // watch may be missing changes to its path. `null` when the run was
  // accepted and hears every place its path can change, or watches nothing.
  fault(): string | null;
}

export interface SourceRunsDeps {
  // Who a shell run's program belongs to.
  readonly launcher: Launcher;
  // What the periods are armed and the refreshes timed on: the daemon's.
  readonly clock: Pick<Timekeeper, "monotonic" | "after" | "every" | "detach">;
  readonly logger?: DaemonLogger;
  // [LAW:single-enforcer] The daemon's one ledger, which every run is recorded
  // in; an owner outside the daemon keeps its own.
  readonly ledger?: RefreshLedger;
  // [LAW:single-enforcer] The daemon's one watcher registry, which holds every
  // watch and polled path a `watch_file` run needs; an owner outside the daemon
  // keeps its own.
  readonly watchers?: WatcherRegistry;
  // [LAW:one-source-of-truth] The daemon's one word on whether the OS is
  // delivering file events, which the watches ride. Only the daemon measures
  // delivery.
  readonly fileEvents?: FileEvents;
}

export class SourceRuns {
  // File-reading policies in the same host share this filesystem edge.
  readonly files = new SourceFiles();
  private readonly byKind: Readonly<
    Record<SourceRead["kind"], KeyedSource<SessionRun, JsonValue>>
  >;
  private readonly watchMgr: PathWatches;
  // Each watching entry's fault, by its run's digest, for the lanes that read
  // it.
  private readonly faults = observable.map<string, string>(undefined, {
    deep: false,
  });

  constructor(deps: SourceRunsDeps) {
    const logger = deps.logger ?? quietLogger;
    const ledger = deps.ledger ?? new RefreshLedger(logger);
    this.watchMgr = new PathWatches(
      deps.watchers ?? new WatcherRegistry({ clock: deps.clock }),
      deps.fileEvents ?? NO_FILE_EVENTS,
    );
    // [LAW:nothing-unseen] One record per read kind (spec section 21's source
    // event): each refresh names its digest, its origin and how many homes
    // share it. A record per digest would grow with every key value a bar
    // ever had.
    const source = (kind: SourceRead["kind"]) =>
      new KeyedSource<SessionRun, JsonValue>({
        name: `source.${kind}`,
        scope: "daemon",
        keyOf: (run) => run.digest,
        // [LAW:nothing-unseen] Its declaration's digest beside its own, so
        // the entry is found from the session's subscriptions that name it.
        fields: ({ digest, run }) =>
          `digest=${shortDigest(digest)} declared=${shortDigest(run.digest)} where=${valueOf(whereOf(run.identity.read))}`,
        // [LAW:single-enforcer] THE run: read → parse. Shell and file are two
        // readers through this one function; text/regex/json are three
        // parsers through it.
        read: async (run, signal) => {
          const reader = readerOf(this.files, deps.launcher, run, signal);
          return parsed(await reader.read(), run.run.parser, reader.where);
        },
        every: ({
          run: {
            identity: { refresh },
          },
        }) =>
          refresh.kind === "ttl"
            ? { okMs: refresh.durationMs, failedMs: refresh.durationMs }
            : null,
        watch: ({ digest, run: { identity } }, changed) => {
          if (identity.refresh.kind !== "watch_file") return NO_WATCH();
          const unsubscribe = this.watchMgr.subscribe(
            identity.refresh.path,
            changed,
            (fault) =>
              runInAction(() => {
                if (fault === null) this.faults.delete(digest);
                else this.faults.set(digest, fault);
              }),
          );
          return () => {
            unsubscribe();
            runInAction(() => this.faults.delete(digest));
          };
        },
        // [LAW:no-ambient-temporal-coupling] A run lives while it is held:
        // the last release drops it, ending its child, its period and its
        // watch, so a key that moves every tick leaves no child behind.
        maxEntries: 0,
        lines: REFRESH_TRIGGERS,
        ledger,
        clock: deps.clock,
      });
    this.byKind = { shell: source("shell"), file: source("file") };
  }

  // [LAW:single-enforcer] The one way to a run: `holds` takes the entry for
  // the session's run of an accepted declaration, created and read once on
  // its first hold, and the lane reads it as it stands. A refused run reaches
  // no reader: its lane answers its refusal for good, and the refusal is its
  // standing fault, so the bar draws the source's fallback beside a ⚠ that
  // says why. A shell run for a session whose environment the host does not
  // hold is refused the same way: the host's own is never a session's.
  declare(
    holds: Holds,
    judged: Judged,
    environment: SessionEnvironment,
  ): SourceLane {
    const { digest } = judged;
    const run = sessionRunOf(judged, environment);
    if (run.kind === "failed") {
      const lane = settledLane<JsonValue>(failed(run.reason, "read"));
      return { digest, current: () => lane.current(), fault: () => run.reason };
    }
    const held = run.value;
    const lane = this.byKind[held.run.identity.read.kind].declare(holds, held);
    // [LAW:one-source-of-truth] Only the run bound to the actual environment
    // knows whether its child received values. A command may transform them.
    return environmentOutput(
      {
        digest,
        current: () => lane.current(),
        fault: () => this.faults.get(held.digest) ?? null,
      },
      Object.keys(held.env).length > 0,
    );
  }

  stats(): SourceRunsStats {
    return {
      shell: this.byKind.shell.stats(),
      file: this.byKind.file.stats(),
      watches: this.watchMgr.size(),
    };
  }

  // Drops every entry, ending its read, its period and its watch.
  close(): void {
    this.byKind.shell.close();
    this.byKind.file.close();
    this.watchMgr.dispose();
  }
}

// [LAW:single-enforcer] The one step from a judged set of runs to the lanes that read
// them: each run is declared in `holds`, inside the caller's one
// `Holds.declare`, so a run dropped from the set is released by that
// declaration's diff and a run two holders share is one entry held twice. The
// collector marks each declaration that throws as a failed lane and declares the rest.
export function declareRuns(
  sourceRuns: Pick<SourceRuns, "declare">,
  holds: Holds,
  runs: ReadonlyMap<string, Judged>,
  environment: SessionEnvironment,
  take: (digest: string, declare: () => SourceLane) => SourceLane,
): ReadonlyMap<string, SourceLane> {
  return new Map(
    [...runs].map(([digest, judged]) => [
      digest,
      take(digest, () => sourceRuns.declare(holds, judged, environment)),
    ]),
  );
}

// [LAW:types-are-the-program] A run as the host keys and spawns it: an
// accepted declaration with the variables it names, at their values in the
// session's environment (spec ADR-8). Its digest is over the declaration's
// digest and those values, so sessions whose named values agree share one
// run and one whose value differs gets its own. A named variable the session does not set is absent from `env`,
// as it is from the process.
export interface SessionRun {
  readonly digest: string;
  readonly run: AcceptedRun;
  readonly env: Environment;
}

// [LAW:single-enforcer] The one step from a judged declaration and a
// session's environment to the run the host holds. A file run names no
// variable, so it reads no environment and is shared by every session.
function sessionRunOf(
  judged: Judged,
  environment: SessionEnvironment,
): Asked<SessionRun> {
  if (judged.kind === "refused")
    return { kind: "failed", reason: `refused: ${judged.reason}` };
  const { run } = judged;
  const { read } = run.identity;
  if (read.kind === "file")
    return { kind: "ok", value: { digest: run.digest, run, env: {} } };
  if (environment.kind === "failed")
    return { kind: "failed", reason: `not run: ${environment.reason}` };
  const session = environment.value;
  const env: Environment = Object.fromEntries(
    read.env.flatMap((name) => {
      const value = ownValue(session, name);
      return value === undefined ? [] : [[name, value]];
    }),
  );
  return {
    kind: "ok",
    value: { digest: digestOf({ run: run.digest, env }), run, env },
  };
}
